/* Camera examples describe individual settings, never a rendered combination. */
'use strict';
const cameraControlDefaults={enabled:false,camera:'Sony VENICE（索尼）',lens:'Zeiss Ultra Prime（蔡司）',focal:'8 mm',aperture:'f/2.8'};
const cameraControlTabs=[['camera','相机'],['lens','镜头'],['focal','焦距'],['aperture','光圈']];
let cameraControlPanel=null,cameraControlIgnoreClickUntil=0;
function cameraControlResolve(d){return {...cameraControlDefaults,...d.creationCamera};}
function cameraControlStep(settings,key,amount){const list=cameraControlCatalog[key];if(!list)return settings;const at=Math.max(0,list.findIndex(item=>item.name===settings[key]));return {...settings,[key]:list[(at+amount%list.length+list.length)%list.length].name};}
function cameraControlTriggerHtml(d){return `<button class="camera-control-trigger ${cameraControlResolve(d).enabled?'is-active':''}" data-action="camera-control-open" aria-label="摄像机控制" title="摄像机控制">${I('camera-control')}</button>`;}
function cameraControlPosition(){const panel=document.querySelector('.camera-control-panel'),trigger=document.querySelector('.camera-control-trigger');if(!panel||!trigger)return;const r=trigger.getBoundingClientRect(),w=Math.min(400,innerWidth-24),h=Math.min(480,innerHeight-24);panel.style.width=w+'px';panel.style.height=h+'px';panel.style.left=Math.max(12,Math.min(innerWidth-w-12,r.left+r.width/2-w/2))+'px';panel.style.top=Math.max(12,Math.min(innerHeight-h-12,r.top-h-10))+'px';}
function cameraControlCurrent(){const p=cameraControlPanel;return cameraControlResolve(canvasCreationDraft(nodeById(p.nodeId)));}
function cameraControlSet(settings){const p=cameraControlPanel;if(!p||p.project!==S.project||!nodeById(p.nodeId))return;(S.nodeDrafts[p.nodeId]??={}).creationCamera=structuredClone(settings);save();cameraControlDraw();document.querySelector('.camera-control-wheel')?.focus({preventScroll:true});}
function cameraControlDraw(){
 const p=cameraControlPanel;if(!p)return;document.querySelector('.camera-control-layer')?.remove();const settings=cameraControlCurrent(),matchedPreset=(S.referenceCameraPresets||[]).find(preset=>['enabled','camera','lens','focal','aperture'].every(key=>preset.settings[key]===settings[key])),list=cameraControlCatalog[p.tab],at=Math.max(0,list.findIndex(item=>item.name===settings[p.tab])),item=list[at],label=cameraControlTabs.find(([key])=>key===p.tab)[1];
 document.body.insertAdjacentHTML('beforeend',`<div class="camera-control-layer"><section class="camera-control-panel" role="dialog" aria-modal="true" aria-label="摄像机控制"><header><strong>摄像机控制</strong><details><summary>${esc(matchedPreset?.name||'默认')}${I('down')}</summary><div class="camera-control-presets"><small>配置预设 (${(S.referenceCameraPresets||[]).length}/20)</small><button data-camera-default>默认<span>恢复初始设置</span></button>${(S.referenceCameraPresets||[]).map(item=>`<button data-camera-preset="${item.id}">${esc(item.name)}</button>`).join('')}<button data-camera-save>+ 保存当前配置为预设</button></div></details><button data-camera-close aria-label="关闭摄像机控制">${I('close')}</button></header><div class="camera-control-preview"><img src="${esc(item.image)}" alt="${esc(item.name)}示例"><small>仅供参考 · 仅展示当前${label}，不代表组合效果</small></div><main><nav role="tablist" aria-label="摄像机控制">${cameraControlTabs.map(([key,name])=>`<button role="tab" data-camera-tab="${key}" aria-selected="${key===p.tab}">${name}</button>`).join('')}</nav><div class="camera-control-wheel" role="listbox" aria-label="${label}" tabindex="0">${[-2,-1,0,1,2].map(offset=>{const option=list[(at+offset+list.length)%list.length];return `<button role="option" aria-selected="${offset===0}" tabindex="-1" data-camera-choice="${esc(option.name)}" class="depth-${Math.abs(offset)}">${['camera','lens'].includes(p.tab)?`<img src="${esc(option.image)}" alt="">`:''}<span>${esc(option.name)}</span></button>`}).join('')}</div></main><footer><div>${cameraControlTabs.map(([key])=>`<button data-camera-tab="${key}" title="${esc(settings[key])}">${esc(settings[key])}</button>`).join('')}</div><button class="camera-control-switch" role="switch" aria-checked="${settings.enabled}" aria-label="启用摄像机控制" data-camera-toggle><span>${settings.enabled?'开启':'关闭'}</span><i></i></button></footer></section></div>`);cameraControlPosition();
}
function cameraControlClose(){document.querySelector('.camera-control-layer')?.remove();cameraControlPanel=null;refreshCanvasCreation();document.querySelector('.camera-control-trigger')?.focus({preventScroll:true});}
function cameraControlOpen(){const n=canvasCreationNode();if(!n||mediaKind(n)!=='image')return;cameraControlPanel={nodeId:n.id,project:S.project,tab:'camera',presetName:null};cameraControlDraw();document.querySelector('.camera-control-wheel').focus();}
const cameraControlAction=handleAction;
handleAction=function(action){if(action==='camera-control-open'){cameraControlOpen();return;}cameraControlAction(action);};
document.addEventListener('click',event=>{
 const p=cameraControlPanel;if(!p)return;const target=event.target;
 if(target.matches('.camera-control-layer')||target.closest('[data-camera-close]')){cameraControlClose();return;}
 const tab=target.closest('[data-camera-tab]'),choice=target.closest('[data-camera-choice]'),preset=target.closest('[data-camera-preset]');
 if(tab){p.tab=tab.dataset.cameraTab;cameraControlDraw();document.querySelector('.camera-control-wheel').focus();return;}
 if(choice){if(performance.now()<cameraControlIgnoreClickUntil)return;p.presetName=null;cameraControlSet({...cameraControlCurrent(),[p.tab]:choice.dataset.cameraChoice});return;}
 if(target.closest('[data-camera-toggle]')){cameraControlSet({...cameraControlCurrent(),enabled:!cameraControlCurrent().enabled});return;}
 if(target.closest('[data-camera-default]')){p.presetName=null;cameraControlSet({...cameraControlDefaults});return;}
 if(preset){const item=(S.referenceCameraPresets||[]).find(item=>item.id===preset.dataset.cameraPreset);if(item){p.presetName=item.name;cameraControlSet(item.settings);}return;}
 if(target.closest('[data-camera-save]')){document.querySelector('.camera-control-panel details').open=false;document.querySelector('.camera-control-panel').insertAdjacentHTML('beforeend',`<div class="image-preset-save-mask"><section role="dialog" aria-modal="true" aria-label="保存相机配置"><h3>保存相机配置</h3><label>名称<input aria-label="相机配置名称" maxlength="60"></label><p role="alert"></p><footer><button data-camera-save-cancel>取消</button><button data-camera-save-confirm>保存</button></footer></section></div>`);document.querySelector('[aria-label="相机配置名称"]').focus();return;}
 if(target.closest('[data-camera-save-cancel]')){document.querySelector('.image-preset-save-mask').remove();return;}
 if(target.closest('[data-camera-save-confirm]')){const mask=document.querySelector('.image-preset-save-mask'),name=mask.querySelector('input').value.trim(),list=S.referenceCameraPresets||[];if(!name||list.some(item=>item.name===name)||list.length>=20){mask.querySelector('[role=alert]').textContent=!name?'请填写配置名称':list.length>=20?'最多保存 20 份配置':'已有同名配置';return;}S.referenceCameraPresets=[...list,{id:studioScriptId('camera-preset'),name,settings:structuredClone(cameraControlCurrent())}];p.presetName=name;save();cameraControlDraw();}
});
let cameraControlDrag=null,cameraWheelTotal=0;
document.addEventListener('wheel',event=>{if(!cameraControlPanel||!event.target.closest('.camera-control-wheel'))return;event.preventDefault();cameraWheelTotal+=event.deltaY;if(Math.abs(cameraWheelTotal)<24)return;const step=Math.sign(cameraWheelTotal);cameraWheelTotal=0;cameraControlPanel.presetName=null;cameraControlSet(cameraControlStep(cameraControlCurrent(),cameraControlPanel.tab,step));},{passive:false});
document.addEventListener('pointerdown',event=>{if(!cameraControlPanel||!event.target.closest('.camera-control-wheel'))return;cameraControlDrag={y:event.clientY};});
document.addEventListener('pointerup',event=>{if(!cameraControlDrag)return;const distance=cameraControlDrag.y-event.clientY;cameraControlDrag=null;if(!cameraControlPanel||Math.abs(distance)<30)return;event.preventDefault();cameraControlIgnoreClickUntil=performance.now()+250;cameraControlPanel.presetName=null;cameraControlSet(cameraControlStep(cameraControlCurrent(),cameraControlPanel.tab,Math.sign(distance)));});
window.addEventListener('keydown',event=>{
 if(!cameraControlPanel)return;event.stopPropagation();const mask=document.querySelector('.camera-control-panel .image-preset-save-mask');
 if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();if(mask)mask.remove();else{const menu=document.querySelector('.camera-control-panel details[open]');if(menu)menu.open=false;else cameraControlClose();}return;}
 if(!mask&&event.target.closest('.camera-control-wheel')&&['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();event.stopImmediatePropagation();cameraControlPanel.presetName=null;cameraControlSet(cameraControlStep(cameraControlCurrent(),cameraControlPanel.tab,event.key==='ArrowDown'?1:-1));return;}
 if(event.key==='Tab'){const root=mask||document.querySelector('.camera-control-panel'),controls=[...root.querySelectorAll('button,input,summary,[role=listbox]')].filter(el=>el.getClientRects().length&&!el.disabled&&el.tabIndex!==-1),at=controls.indexOf(document.activeElement);if(event.shiftKey&&at<=0){event.preventDefault();controls.at(-1)?.focus();}else if(!event.shiftKey&&(at<0||at===controls.length-1)){event.preventDefault();controls[0]?.focus();}}
},true);
window.addEventListener('resize',cameraControlPosition);
if(document.getElementById('viewport'))refreshCanvasCreation();
